using Microsoft.EntityFrameworkCore;
using NihongoAcademy.Models;
using System.Text.Json;

namespace NihongoAcademy.Data
{
    public static partial class DataSeeder
    {
        private sealed record ListeningQuestionSeed(string Type, string Prompt, string Answer, string Explanation, params string[] Options);
        private sealed record ListeningSeed(string Code, string Title, string JapaneseTitle, string Level, string Type, string Lesson,
            string Situation, string Japanese, string English, string[] Tips, params ListeningQuestionSeed[] Questions);

        internal static async Task SeedListeningCurriculumAsync(ApplicationDbContext context)
        {
            var seeds = new[]
            {
                new ListeningSeed("a1-first-meeting","A First Meeting","はじめて会う","A1","dialogue","A1: Greetings for the situation","Two students meet before class.","A：はじめまして。田中です。お名前は何ですか。\nB：リーです。マレーシアから来ました。よろしくお願いします。","A: Nice to meet you. I'm Tanaka. What is your name?\nB: I'm Lee. I came from Malaysia. Nice to meet you.",new[]{"Listen for names.","から来ました introduces a place of origin."},
                    new("choice","What is the new student's name?","リー","The speaker says リーです.","田中","リー","マリア","山田"),new("choice","Where is Lee from?","Malaysia","マレーシアから来ました means came from Malaysia.","Japan","Malaysia","China","Korea"),new("dictation","Type the polite closing you hear.","よろしくお願いします","This fixed expression closes a first introduction politely.")),
                new ListeningSeed("a1-family-photo","A Family Photo","家族の写真","A1","dialogue","A1: Talk about your family","Friends look at a family photograph.","A：これはだれですか。\nB：わたしの姉です。姉は大学生です。となりは母です。","A: Who is this?\nB: My older sister. She is a university student. Next to her is my mother.",new[]{"だれ asks who.","Listen for relationship words before occupations."},new("choice","Who is a university student?","The older sister","姉 is the older sister.","The mother","The older sister","The father","The speaker"),new("choice","Who is next to the sister?","The mother","となりは母です identifies the mother.","The father","A teacher","The mother","A friend"),new("dictation","Type the family relationship in: わたしの___です。","姉","The missing word is 姉.")),
                new ListeningSeed("a1-schedule","Morning Schedule","朝の予定","A1","announcement","A1: Tell time and make a schedule","A student explains the morning routine.","毎朝七時に起きます。七時半に朝ごはんを食べます。八時十五分に学校へ行きます。","Every morning I wake at seven, eat breakfast at seven thirty, and go to school at eight fifteen.",new[]{"Write the times in order.","に marks a specific action time."},new("choice","What happens at 7:30?","Breakfast","七時半に朝ごはんを食べます.","Wake up","Breakfast","Go to school","Go to bed"),new("choice","When does the student go to school?","8:15","八時十五分 is 8:15.","7:00","7:30","8:00","8:15"),new("dictation","Type the first action verb you hear.","起きます","The first action is 起きます.")),
                new ListeningSeed("a1-cafe","At the Cafe","カフェで","A1","dialogue","A1: Order food and drinks","A customer orders lunch.","店員：いらっしゃいませ。\n客：コーヒーを一杯と、サンドイッチを一つお願いします。\n店員：はい。千二百円です。","Staff: Welcome.\nCustomer: One coffee and one sandwich, please.\nStaff: Certainly. It is 1,200 yen.",new[]{"Listen separately for item, quantity and price.","一杯 counts drinks."},new("choice","What drink is ordered?","Coffee","コーヒーを一杯 is one coffee.","Tea","Water","Coffee","Juice"),new("choice","How much is the order?","1,200 yen","千二百円 is 1,200 yen.","200 yen","800 yen","1,000 yen","1,200 yen"),new("dictation","Type the polite request at the end of the order.","お願いします","The customer ends with お願いします.")),
                new ListeningSeed("a1-shopping","Shopping for a Shirt","シャツを買う","A1","dialogue","A1: Shop for an item","A customer asks about a shirt.","客：この青いシャツはいくらですか。\n店員：三千円です。\n客：白いシャツもありますか。\n店員：はい、あります。","Customer: How much is this blue shirt?\nStaff: 3,000 yen.\nCustomer: Do you also have a white shirt?\nStaff: Yes.",new[]{"Colour words come before シャツ.","も means also."},new("choice","Which shirt is 3,000 yen?","The blue shirt","The first question identifies the blue shirt.","The red shirt","The blue shirt","The white shirt","The black shirt"),new("choice","Which other colour is available?","White","白いシャツもありますか asks about white.","Red","Green","White","Black"),new("dictation","Type the availability question ending.","ありますか","ありますか asks whether something is available.")),
                new ListeningSeed("a1-weekend-plan","Weekend Plan","週末の予定","A1","dialogue","A1: Invite someone and make a plan","Friends arrange a movie.","A：土曜日、いっしょに映画を見ませんか。\nB：いいですね。何時ですか。\nA：二時です。一時半に駅で会いましょう。","A: Shall we see a movie Saturday?\nB: Sounds good. What time?\nA: At two. Let's meet at the station at 1:30.",new[]{"Distinguish the meeting time from the movie time.","ませんか is the invitation."},new("choice","When is the movie?","2:00","二時です gives the movie time.","1:00","1:30","2:00","2:30"),new("choice","Where will they meet?","At the station","駅で会いましょう means meet at the station.","At school","At a cafe","At the station","At the cinema"),new("dictation","Type the invitation ending.","見ませんか","The invitation is 見ませんか.")),
                new ListeningSeed("a2-weekend-story","Weekend Story","週末の話","A2","story","A2: Connect actions and describe a sequence","A friend describes Sunday.","日曜日は友だちと町へ行きました。まずカフェで昼ごはんを食べて、それから映画を見ました。映画は長かったですが、おもしろかったです。","On Sunday I went into town with a friend. First we ate lunch at a cafe, then watched a film. It was long but interesting.",new[]{"Use まず and それから to track sequence.","ですが introduces contrast."},new("choice","What happened first in town?","They ate lunch","まず introduces lunch first.","They watched a film","They shopped","They ate lunch","They went home"),new("choice","How was the film?","Long but interesting","長かったですが、おもしろかったです.","Short and boring","Long but interesting","Scary","Expensive"),new("dictation","Type the sequence word meaning 'after that'.","それから","それから introduces the next event.")),
                new ListeningSeed("a2-experience","Travel Experience","旅行の経験","A2","dialogue","A2: Talk about experiences","Two people discuss Kyoto.","A：京都に行ったことがありますか。\nB：はい、二回行ったことがあります。去年は春に行って、お寺をたくさん見ました。","A: Have you been to Kyoto?\nB: Yes, twice. Last year I went in spring and saw many temples.",new[]{"Listen for the experience pattern.","回 counts occurrences."},new("choice","How many times has B visited Kyoto?","Twice","二回 means twice.","Never","Once","Twice","Three times"),new("choice","What did B see?","Many temples","お寺をたくさん見ました.","Mountains","Many temples","A festival","Friends"),new("dictation","Type the experience phrase after 行った.","ことがありますか","ことがありますか asks about experience.")),
                new ListeningSeed("a2-comparison","Train or Bus","電車かバスか","A2","dialogue","A2: Compare choices","Friends choose transportation.","A：駅まで行くなら、電車とバスでは、どちらがいいですか。\nB：電車のほうがバスより速いです。でも、バスのほうが安いです。","A: Which is better for getting to the station, the train or the bus?\nB: The train is faster, but the bus is cheaper.",new[]{"Track which quality belongs to each option.","のほうが and より signal comparison."},new("choice","Which is faster?","The train","電車のほうがバスより速いです.","The bus","The train","They are equal","It is not stated"),new("choice","Which is cheaper?","The bus","バスのほうが安いです.","The train","The bus","They cost the same","A taxi"),new("dictation","Type the word meaning 'than'.","より","より marks the comparison baseline.")),
                new ListeningSeed("a2-hotel-problem","A Hotel Problem","ホテルの問題","A2","dialogue","A2: Explain a problem and ask for help","A guest calls the front desk.","客：すみません。部屋のエアコンをつけましたが、冷たい風が出ません。見に来ていただけませんか。\n係：はい、すぐ行きます。","Guest: Excuse me. I turned on the air conditioner, but no cold air comes out. Could you come and look?\nStaff: Yes, right away.",new[]{"Identify the device and exact symptom.","いただけませんか makes a polite request."},new("choice","What is the problem?","No cold air comes out","冷たい風が出ません describes the symptom.","The window is broken","No cold air comes out","There is no water","The room is noisy"),new("choice","When will staff come?","Right away","すぐ means right away.","Tomorrow","In an hour","Right away","After dinner"),new("dictation","Type the polite request ending.","いただけませんか","いただけませんか softens the request.")),
                new ListeningSeed("a2-study-advice","Study Advice","勉強のアドバイス","A2","conversation","A2: Express obligation and advice","A student receives study advice.","A：漢字がなかなか覚えられません。\nB：毎日少しずつ書いたほうがいいですよ。文の中で使うと、もっと覚えやすくなります。","A: I cannot easily remember kanji.\nB: You should write a little every day. If you use them in sentences, they become easier to remember.",new[]{"Listen for the difficulty first, then two suggestions.","ほうがいい gives advice."},new("choice","What is difficult for A?","Remembering kanji","漢字がなかなか覚えられません.","Speaking","Remembering kanji","Listening","Finding a book"),new("choice","What should A do every day?","Write a little","毎日少しずつ書いたほうがいい.","Watch films","Write a little","Take a test","Travel"),new("dictation","Type the advice ending.","ほうがいいですよ","ほうがいいですよ expresses friendly advice.")),
                new ListeningSeed("a2-opinion","Travel Opinion","旅行についての意見","A2","conversation","A2: Report information and opinions","A student reports a friend's suggestion.","山田さんは京都が便利だと言っていました。私も文化をもっと知りたいので、京都がいいと思います。今夜ホテルを調べるつもりです。","Yamada said Kyoto is convenient. I also think Kyoto is good because I want to learn more about culture. I intend to look for a hotel tonight.",new[]{"Separate reported speech from the speaker's opinion.","つもりです states an intention."},new("choice","What did Yamada say?","Kyoto is convenient","The clause before と言っていました is Yamada's statement.","Tokyo is cheaper","Kyoto is convenient","The hotel is full","The train is late"),new("choice","What will the speaker do tonight?","Look for a hotel","ホテルを調べるつもりです.","Call Yamada","Buy a ticket","Look for a hotel","Visit a museum"),new("dictation","Type the phrase meaning 'I think'.","と思います","と思います introduces the speaker's opinion."))
            };

            foreach (var (seed, seedIndex) in seeds.Select((value, index) => (value, index)))
            {
                var lessonId = await context.Lessons.Where(l => l.Title == seed.Lesson).Select(l => (int?)l.Id).SingleOrDefaultAsync();
                var task = await context.ListeningTasks.Include(t => t.Questions).SingleOrDefaultAsync(t => t.Code == seed.Code);
                if (task == null) { task = new ListeningTask { Code = seed.Code }; context.ListeningTasks.Add(task); }
                task.Title = seed.Title; task.JapaneseTitle = seed.JapaneseTitle; task.Level = seed.Level; task.TaskType = seed.Type;
                task.Situation = seed.Situation; task.ScriptJapanese = seed.Japanese; task.ScriptEnglish = seed.English;
                task.ListeningTipsJson = JsonSerializer.Serialize(seed.Tips); task.EstimatedMinutes = 6; task.LessonId = lessonId; task.DisplayOrder = seedIndex + 1;
                await context.SaveChangesAsync();
                for (var i = 0; i < seed.Questions.Length; i++)
                {
                    var item = seed.Questions[i]; var order = i + 1;
                    var question = task.Questions.FirstOrDefault(q => q.DisplayOrder == order);
                    if (question == null) { question = new ListeningQuestion { ListeningTaskId = task.Id, DisplayOrder = order }; context.ListeningQuestions.Add(question); }
                    question.QuestionType = item.Type; question.Prompt = item.Prompt; question.CorrectAnswer = item.Answer;
                    question.Explanation = item.Explanation; question.OptionsJson = item.Options.Length == 0 ? null : JsonSerializer.Serialize(item.Options);
                }
                context.ListeningQuestions.RemoveRange(task.Questions.Where(q => q.DisplayOrder > seed.Questions.Length));
            }
            await context.SaveChangesAsync();
            if (await context.ListeningTasks.CountAsync() < seeds.Length || await context.ListeningQuestions.CountAsync() < seeds.Length * 3)
                throw new InvalidOperationException("The structured listening curriculum is incomplete.");
        }
    }
}
